def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    # Endgame: squeeze the final rounds while trusting a cooperative partner a bit longer.
    if n >= 97:
        if opp_d == 0:
            return 'D'
        if opp_c * 3 >= n:
            return 'D'
        return 'D'

    if n >= 10:
        recent_opp = opp[-10:]
        recent_d = recent_opp.count('D')
        # Persistent defector: punish, but probe rarely to avoid getting stuck.
        if recent_d >= 8:
            if rng.random() < 0.06:
                return 'C'
            return 'D'
        # Highly cooperative: exploit gently and keep cooperation dominant.
        if recent_d <= 1:
            if n >= 8 and n % 13 == 0 and opp_d >= 1:
                return 'D'
            return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            # Long mutual defection: attempt repair with increasing willingness.
            if n >= 4 and opp[-4:].count('D') >= 3:
                if rng.random() < 0.22:
                    return 'C'
                return 'D'
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        else:
            # They defected while we cooperated. Short punishment, then reopen.
            exploit_streak = 0
            for i in range(n - 1, -1, -1):
                if me[i] == 'C' and opp[i] == 'D':
                    exploit_streak += 1
                else:
                    break
            if exploit_streak >= 2:
                return 'D'
            if opp_d >= 10 and opp_c >= 10:
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            if rng.random() < 0.25:
                return 'D'
            return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        run_c = 0
        for a in reversed(opp):
            if a == 'C':
                run_c += 1
            else:
                break
        # After long cooperation, occasionally exploit—but keep it rare and safe.
        if run_c >= 6 and n >= 20:
            if n % 17 == 0 and rng.random() < 0.5:
                return 'D'
        if run_c >= 4 and n >= 25 and opp_d == 0 and n % 23 == 0:
            return 'D'
        return 'C'

    return 'C'
